import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const sut = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])(
    "returns 0 for subtotalCents=%i",
    (subtotal) => {
      expect(sut.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent=%s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent=%i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const sut = new PercentageDiscountPolicy(10);
      expect(sut.computeDiscountCents(10_000)).toBe(1_000);
    });

    it("rounds down to nearest cent (floors)", () => {
      const sut = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 → 33
      expect(sut.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → 33
      expect(sut.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new PercentageDiscountPolicy(50);
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new PercentageDiscountPolicy(50);
      expect(sut.computeDiscountCents(-500)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const sut = new PercentageDiscountPolicy(100);
      expect(sut.computeDiscountCents(5_000)).toBe(5_000);
    });

    it("0% discount returns 0", () => {
      const sut = new PercentageDiscountPolicy(0);
      expect(sut.computeDiscountCents(5_000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns amountCents when subtotal exceeds it", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(1_000)).toBe(500);
    });

    it("caps at subtotal when amountCents exceeds subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(2_000);
      expect(sut.computeDiscountCents(1_000)).toBe(1_000);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when equal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent policy results against original subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(sut.computeDiscountCents(10_000)).toBe(1_500);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });

    it("sum can exceed subtotal (clamping is done by Cart)", () => {
      // Two fixed-amount discounts that together exceed subtotal
      const sut = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "sum",
      );
      // Each returns min(800, 1000) = 800, sum = 1600 > 1000
      expect(sut.computeDiscountCents(1_000)).toBe(1_600);
    });

    it("defaults to sum mode when not specified", () => {
      const sut = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500, fixed = 200 → sum = 700
      expect(sut.computeDiscountCents(5_000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to the remaining subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining = 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900, remaining = 8100
        ],
        "chain",
      );
      expect(sut.computeDiscountCents(10_000)).toBe(1_900);
    });

    it("order matters in chain mode", () => {
      // Fixed first, then percentage
      const sut1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1_000), // 1000 off 10000, remaining = 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900
        ],
        "chain",
      );
      // Percentage first, then fixed
      const sut2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining = 9000
          new FixedAmountDiscountPolicy(1_000), // min(1000, 9000) = 1000
        ],
        "chain",
      );
      expect(sut1.computeDiscountCents(10_000)).toBe(1_900);
      expect(sut2.computeDiscountCents(10_000)).toBe(2_000);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1_000), // takes all 1000
          new PercentageDiscountPolicy(50), // 50% of 0 = 0
        ],
        "chain",
      );
      expect(sut.computeDiscountCents(1_000)).toBe(1_000);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });
  });
});

