describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 10.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([], 5_000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLineNoWeight("a")], 5_000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLine("a", 300)], 5_000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      // weight = 500 → first bracket (upToGrams: 500)
      expect(sut.computeShippingCents([makeLine("a", 500)], 5_000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      // weight = 501 → second bracket (upToGrams: 1000)
      expect(sut.computeShippingCents([makeLine("a", 501)], 5_000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLine("a", 5000)], 5_000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const sut = new WeightBasedShippingCalculator(brackets, 2_000);
      expect(sut.computeShippingCents([makeLine("a", 5001)], 5_000)).toBe(2_000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLine("a", 9999)], 5_000)).toBe(1200);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const sut = new WeightBasedShippingCalculator(unsorted);
      expect(sut.computeShippingCents([makeLine("a", 300)], 5_000)).toBe(300);
      expect(sut.computeShippingCents([makeLine("a", 800)], 5_000)).toBe(600);
    });

    it("sums weight across multiple lines with quantity", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      // 200g * 3 = 600g → second bracket
      expect(
        sut.computeShippingCents([makeLine("a", 200, 3)], 5_000),
      ).toBe(600);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
