import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const sut = new NoTaxCalculator();

  it.each([
    [1_000, "US"],
    [0, "FR"],
    [-500, "DE"],
  ])("returns 0 for taxableCents=%i region=%s", (cents, region) => {
    expect(sut.computeTaxCents(cents, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.5)).toThrow(RangeError);
    });

    it("rejects negative defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.1)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects invalid rate in rates map", () => {
      expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
    });

    it("rejects negative rate in rates map", () => {
      expect(() => new RegionalTaxCalculator({ "US": -0.01 })).toThrow(RangeError);
    });

    it("accepts valid rates and defaultRate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0.08, "FR": 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const sut = new RegionalTaxCalculator(
      { "US": 0.08, "US-CA": 0.0875, "FR": 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8% of 10000 = 800
      expect(sut.computeTaxCents(10_000, "US")).toBe(800);
    });

    it("uses sub-region rate for US-CA", () => {
      // 8.75% of 10000 = 875
      expect(sut.computeTaxCents(10_000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(sut.computeTaxCents(10_000, "JP")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 333 = 66.6 → 66
      expect(sut.computeTaxCents(333, "FR")).toBe(66);
    });

    it("returns 0 for zero taxable", () => {
      expect(sut.computeTaxCents(0, "US")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(sut.computeTaxCents(-100, "US")).toBe(0);
    });

    it("returns 0 when rate is 0 and no default", () => {
      const noDefault = new RegionalTaxCalculator({ "US": 0 });
      expect(noDefault.computeTaxCents(10_000, "US")).toBe(0);
    });

    it("uses default rate 0 when not specified", () => {
      const noDefault = new RegionalTaxCalculator({});
      expect(noDefault.computeTaxCents(10_000, "UNKNOWN")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from an async rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    const result = await sut.computeTaxCents(10_000, "US");
    expect(result).toBe(1_000);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    const result = await sut.computeTaxCents(0, "US");
    expect(result).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    const result = await sut.computeTaxCents(-500, "US");
    expect(result).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.07),
    };
    const sut = new AsyncTaxCalculator(provider);
    // 7% of 999 = 69.93 → 69
    expect(await sut.computeTaxCents(999, "US")).toBe(69);
  });

  it("throws RangeError when provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(10_000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(10_000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(10_000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(10_000, "US")).rejects.toThrow(
      "network error",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 300 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(200 * 2 + 300 * 3);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

